323	  resolver.AddConcatenation();
324	  resolver.AddConv2D();
325	  resolver.AddExpandDims();
326	  resolver.AddFullyConnected();
327	  resolver.AddLogistic();
328	  resolver.AddMean();
329	  resolver.AddMul();
330	  resolver.AddPad();
331	  resolver.AddReshape();
332	  resolver.AddStridedSlice();
333	  resolver.AddSum();
334	  resolver.AddTranspose();
335	
336	  tflite::MicroInterpreter interp(model, resolver, tensor_arena, kArenaSize);
337	  if (interp.AllocateTensors() != kTfLiteOk) {
338	    printf("ERROR: AllocateTensors failed\n");
