373	           input_samples, reference_samples);
374	    cleanup_main();
375	    return 1;
376	  }
377	  const size_t regression_samples = input_samples;
378	  const size_t output_elements = output_sample_bytes / sizeof(float);
379	
380	  float regression_max_abs_error = 0.0f;
381	  size_t worst_sample = 0;
382	  size_t worst_element = 0;
383	  float worst_got = 0.0f;
384	  float worst_reference = 0.0f;
385	  for (size_t sample = 0; sample < regression_samples; ++sample) {
386	    memcpy(input->data.raw, input_data + sample * input_sample_bytes,
387	           input_sample_bytes);
