389	      printf("ERROR: regression Invoke failed at sample %zu\n", sample);
390	      cleanup_main();
391	      return 1;
392	    }
393	
394	    const float* got = reinterpret_cast<const float*>(output->data.raw);
395	    const float* reference = reinterpret_cast<const float*>(
396	        ref_data + sample * output_sample_bytes);
397	    for (size_t element = 0; element < output_elements; ++element) {
398	      const float difference = std::fabs(got[element] - reference[element]);
399	      if (!std::isfinite(got[element]) ||
400	          !std::isfinite(reference[element]) ||
401	          !std::isfinite(difference)) {
402	        printf("ERROR: regression non-finite sample=%zu element=%zu\n",
403	               sample, element);
