#!/usr/bin/env python3
"""
Parse .tflite using the tflite Python schema package and compute:
- Model size (ROM, bytes)
- Total params (weights + biases, bytes)
- MACs per layer and total
- Primary operators list
"""

import sys
import os
import numpy as np
from tflite.Model import Model
from tflite.TensorType import TensorType

TYPE_SIZES = {
    TensorType.FLOAT32: 4, TensorType.FLOAT16: 2, TensorType.INT32: 4,
    TensorType.UINT8: 1, TensorType.INT64: 8, TensorType.STRING: 1,
    TensorType.BOOL: 1, TensorType.INT16: 2, TensorType.COMPLEX64: 8,
    TensorType.INT8: 1, TensorType.FLOAT64: 8, TensorType.COMPLEX128: 16,
    TensorType.UINT64: 8,
}

def shape_size(shape):
    """Compute number of elements from a shape list (skip 0/-1 dynamic dims)."""
    n = 1
    for d in shape:
        if d is not None and d > 0:
            n *= d
    return n

def compute_conv2d_macs(input_shape, filter_shape, output_shape):
    """CONV2D: output NHWC, filter OHWI. MACs = B*H*W*C_out*C_in*K_h*K_w"""
    if len(output_shape) >= 4 and len(filter_shape) >= 4:
        b = output_shape[0] if output_shape[0] > 0 else 1
        h_out, w_out, c_out = output_shape[1], output_shape[2], output_shape[3]
        # filter OHWI
        c_out_f = filter_shape[0]
        k_h, k_w, c_in = filter_shape[1], filter_shape[2], filter_shape[3]
        c_out = c_out if c_out > 0 else c_out_f
        return b * h_out * w_out * c_out * c_in * k_h * k_w
    return 0

def compute_depthwise_conv2d_macs(input_shape, filter_shape, output_shape):
    """DEPTHWISE_CONV2D: filter is [1, K_h, K_w, C*multiplier]"""
    if len(output_shape) >= 4 and len(filter_shape) >= 4:
        b = output_shape[0] if output_shape[0] > 0 else 1
        h_out, w_out, c_out = output_shape[1], output_shape[2], output_shape[3]
        k_h, k_w = filter_shape[1], filter_shape[2]
        return b * h_out * w_out * c_out * k_h * k_w
    return 0

def compute_fc_macs(input_shape, filter_shape, output_shape):
    """FULLY_CONNECTED: filter [num_units, input_dim]"""
    if len(filter_shape) >= 2:
        b = 1
        for d in output_shape[:-1]:
            if d and d > 0:
                b *= d
        n_units = filter_shape[0]
        n_input = 1
        for d in filter_shape[1:]:
            if d and d > 0:
                n_input *= d
        return b * n_units * n_input
    return 0

def compute_transpose_conv_macs(filter_shape, output_shape):
    """TRANSPOSE_CONV: filter OHWI, output NHWC"""
    if len(output_shape) >= 4 and len(filter_shape) >= 4:
        b = output_shape[0] if output_shape[0] > 0 else 1
        h_out, w_out, c_out = output_shape[1], output_shape[2], output_shape[3]
        k_h, k_w, c_in = filter_shape[1], filter_shape[2], filter_shape[3]
        return b * h_out * w_out * c_out * c_in * k_h * k_w
    return 0

def compute_lstm_macs(input_shape, weights_shapes):
    """LSTM: estimate MACs from input-to-hidden and hidden-to-hidden weights."""
    macs = 0
    for ws in weights_shapes:
        if len(ws) >= 2:
            macs += ws[0] * ws[1]  # rough: output_dim * input_dim
    return macs

def get_tensor_shape(tensor):
    """Extract shape from a Tensor object."""
    if tensor.Shape() is None:
        return []
    shape = []
    for i in range(tensor.ShapeLength()):
        d = tensor.Shape(i)
        shape.append(d)
    return shape

def get_tensor_type(tensor):
    return tensor.Type()

def parse_model(filepath):
    """Parse .tflite and return (model_size, total_params_bytes, total_macs, op_summary, primary_ops)."""
    with open(filepath, 'rb') as f:
        buf = f.read()

    model_size = len(buf)
    model = Model.GetRootAs(buf, 0)

    # Collect buffers
    buffer_sizes = []
    for i in range(model.BuffersLength()):
        buf_obj = model.Buffers(i)
        if buf_obj.Data() is not None:
            buffer_sizes.append(buf_obj.DataLength())
        else:
            buffer_sizes.append(0)

    total_macs = 0
    total_params = 0
    op_summary = []
    primary_ops = {}  # op_name -> count

    # Process first subgraph (primary)
    n_subgraphs = model.SubgraphsLength()
    for sg_idx in range(n_subgraphs):
        sg = model.Subgraphs(sg_idx)

        # Collect tensors
        tensors = []
        for t_idx in range(sg.TensorsLength()):
            t = sg.Tensors(t_idx)
            tensors.append({
                'shape': get_tensor_shape(t),
                'type': get_tensor_type(t),
                'buffer_idx': t.Buffer(),
            })

        # Collect operator codes
        opcode_names = []
        for oc_idx in range(model.OperatorCodesLength()):
            oc = model.OperatorCodes(oc_idx)
            # BuiltinCode or DeprecatedBuiltinCode
            builtin_code = oc.BuiltinCode()
            if builtin_code == 0:  # CUSTOM
                custom = oc.CustomCode()
                if custom:
                    opcode_names.append(custom.decode('utf-8') if isinstance(custom, bytes) else str(custom))
                else:
                    opcode_names.append("CUSTOM")
            else:
                # Map builtin code to name
                opcode_names.append(builtin_code_name(builtin_code))

        # Process operators
        for op_idx in range(sg.OperatorsLength()):
            op = sg.Operators(op_idx)
            opcode_idx = op.OpcodeIndex()
            opcode_name = opcode_names[opcode_idx] if opcode_idx < len(opcode_names) else "UNKNOWN"

            # Get inputs/outputs
            inputs = [op.Inputs(i) for i in range(op.InputsLength())]
            outputs = [op.Outputs(i) for i in range(op.OutputsLength())]

            macs = 0

            if opcode_name == "CONV_2D" and len(inputs) >= 2:
                in_t = tensors[inputs[0]] if inputs[0] < len(tensors) else None
                w_t = tensors[inputs[1]] if inputs[1] < len(tensors) else None
                out_t = tensors[outputs[0]] if outputs and outputs[0] < len(tensors) else None
                if in_t and w_t and out_t:
                    macs = compute_conv2d_macs(in_t['shape'], w_t['shape'], out_t['shape'])
            elif opcode_name == "DEPTHWISE_CONV_2D" and len(inputs) >= 2:
                in_t = tensors[inputs[0]] if inputs[0] < len(tensors) else None
                w_t = tensors[inputs[1]] if inputs[1] < len(tensors) else None
                out_t = tensors[outputs[0]] if outputs and outputs[0] < len(tensors) else None
                if in_t and w_t and out_t:
                    macs = compute_depthwise_conv2d_macs(in_t['shape'], w_t['shape'], out_t['shape'])
            elif opcode_name == "FULLY_CONNECTED" and len(inputs) >= 2:
                in_t = tensors[inputs[0]] if inputs[0] < len(tensors) else None
                w_t = tensors[inputs[1]] if inputs[1] < len(tensors) else None
                out_t = tensors[outputs[0]] if outputs and outputs[0] < len(tensors) else None
                if in_t and w_t and out_t:
                    macs = compute_fc_macs(in_t['shape'], w_t['shape'], out_t['shape'])
            elif opcode_name == "TRANSPOSE_CONV" and len(inputs) >= 3:
                w_t = tensors[inputs[1]] if inputs[1] < len(tensors) else None
                out_t = tensors[inputs[2]] if inputs[2] < len(tensors) else None
                if w_t and out_t:
                    macs = compute_transpose_conv_macs(w_t['shape'], out_t['shape'])
            elif opcode_name in ("LSTM", "UNIDIRECTIONAL_SEQUENCE_LSTM"):
                # All weight inputs (indices 1+)
                w_shapes = []
                for wi in inputs[1:]:
                    if wi < len(tensors):
                        w_shapes.append(tensors[wi]['shape'])
                macs = compute_lstm_macs(tensors[inputs[0]]['shape'] if inputs[0] < len(tensors) else [], w_shapes)
            elif opcode_name in ("UNIDIRECTIONAL_SEQUENCE_GRU", "BIDIRECTIONAL_SEQUENCE_GRU"):
                # GRU: 3 gates * (input_dim + hidden_dim) * hidden_dim
                # inputs typically: input, weights_input, weights_recurrent, bias, ...
                w_shapes = []
                for wi in inputs[1:]:
                    if wi < len(tensors):
                        w_shapes.append(tensors[wi]['shape'])
                macs = compute_lstm_macs([], w_shapes)

            total_macs += macs

            # Track primary ops
            primary_ops[opcode_name] = primary_ops.get(opcode_name, 0) + 1

            if macs > 0:
                # Get weight element count
                w_idx = None
                if opcode_name in ("CONV_2D", "DEPTHWISE_CONV_2D", "FULLY_CONNECTED") and len(inputs) >= 2:
                    w_idx = inputs[1]
                elif opcode_name == "TRANSPOSE_CONV" and len(inputs) >= 3:
                    w_idx = inputs[1]
                w_elems = 0
                if w_idx is not None and w_idx < len(tensors):
                    w_elems = shape_size(tensors[w_idx]['shape'])
                op_summary.append((opcode_name, macs, w_elems))

            # Sum param bytes (weights + biases)
            param_indices = set()
            if opcode_name in ("CONV_2D", "DEPTHWISE_CONV_2D", "FULLY_CONNECTED"):
                # input[1]=weight, input[2]=bias (if present)
                for bi in inputs[1:]:
                    if bi < len(tensors):
                        buf_idx = tensors[bi]['buffer_idx']
                        if buf_idx < len(buffer_sizes):
                            param_indices.add(buf_idx)
            elif opcode_name == "TRANSPOSE_CONV":
                if len(inputs) >= 2 and inputs[1] < len(tensors):
                    buf_idx = tensors[inputs[1]]['buffer_idx']
                    if buf_idx < len(buffer_sizes):
                        param_indices.add(buf_idx)
            elif opcode_name in ("LSTM", "UNIDIRECTIONAL_SEQUENCE_LSTM",
                                  "UNIDIRECTIONAL_SEQUENCE_GRU", "BIDIRECTIONAL_SEQUENCE_GRU"):
                # All non-input tensors
                for bi in inputs[1:]:
                    if bi < len(tensors):
                        buf_idx = tensors[bi]['buffer_idx']
                        if buf_idx < len(buffer_sizes):
                            param_indices.add(buf_idx)
            else:
                # For other ops, count input[1+] buffers that have data
                for bi in inputs[1:]:
                    if bi < len(tensors):
                        buf_idx = tensors[bi]['buffer_idx']
                        if buf_idx < len(buffer_sizes) and buffer_sizes[buf_idx] > 0:
                            param_indices.add(buf_idx)

            for bi in param_indices:
                total_params += buffer_sizes[bi]

    # Primary operators summary (top by count)
    primary_ops_str = ", ".join(f"{name}×{cnt}" for name, cnt in sorted(primary_ops.items(), key=lambda x: -x[1])[:8])

    return model_size, total_params, total_macs, op_summary, primary_ops_str

def builtin_code_name(code):
    """Map TFLite BuiltinOperator enum to name."""
    names = {
        0: "ADD", 1: "AVERAGE_POOL_2D", 2: "CONCATENATION", 3: "CONV_2D",
        4: "DEPTHWISE_CONV_2D", 5: "DEPTH_TO_SPACE", 6: "DEQUANTIZE",
        7: "ELU", 8: "EMBEDDING_LOOKUP", 9: "FULLY_CONNECTED",
        10: "LSH_PROJECTION", 11: "LSTM", 12: "MAX_POOL_2D",
        13: "MUL", 14: "RELU", 15: "RELU_N1_TO_1", 16: "RESHAPE",
        17: "RESIZE_BILINEAR", 18: "RNN", 19: "SOFTMAX",
        20: "SPACE_TO_DEPTH", 21: "SVDF", 22: "TRANSPOSE",
        23: "MEAN", 24: "SUB", 25: "PACK", 26: "PAD",
        27: "SPLIT", 28: "STRIDED_SLICE", 29: "SQUEEZE", 30: "TANH",
        31: "UNPACK", 32: "LOGISTIC", 33: "ABS", 34: "NEG",
        35: "SIN", 36: "COS", 37: "SQRT", 38: "RSQRT",
        39: "PADV2", 40: "CAST", 41: "PRELU", 42: "EXP",
        43: "FAKE_QUANT", 44: "FLOOR", 45: "LOG", 46: "LOG_SOFTMAX",
        47: "LOGICAL_AND", 48: "LOGICAL_OR", 49: "LOGICAL_NOT",
        50: "MAXIMUM", 51: "MINIMUM", 52: "MIRROR_PAD", 53: "LESS",
        54: "EQUAL", 55: "NOT_EQUAL", 56: "GREATER", 57: "GREATER_EQUAL",
        58: "LESS_EQUAL", 59: "SELECT", 60: "SLICE", 61: "SINH",
        62: "TANH", 63: "TRANSPOSE_CONV", 64: "SHAPE", 65: "QUANTIZE",
        66: "DEQUANTIZE2", 67: "RESHAPE2",
        68: "BATCH_TO_SPACE_ND", 69: "SPACE_TO_BATCH_ND",
        70: "PACK2", 71: "UNIDIRECTIONAL_SEQUENCE_LSTM",
        72: "BIDIRECTIONAL_SEQUENCE_LSTM", 73: "BIDIRECTIONAL_SEQUENCE_RNN",
        74: "UNIDIRECTIONAL_SEQUENCE_GRU", 75: "BIDIRECTIONAL_SEQUENCE_GRU",
        76: "MULTI_HEAD_ATTENTION",
    }
    return names.get(code, f"BUILTIN_{code}")

def format_bytes(b):
    if b >= 1024 * 1024:
        return f"{b} ({b/1024/1024:.2f} MB)"
    elif b >= 1024:
        return f"{b} ({b/1024:.1f} KB)"
    return f"{b}"

def format_macs(m):
    if m >= 1_000_000_000:
        return f"{m:,} ({m/1e9:.2f} GMACs)"
    elif m >= 1_000_000:
        return f"{m:,} ({m/1e6:.2f} MMACs)"
    elif m >= 1000:
        return f"{m:,} ({m/1e3:.1f} KMACs)"
    return f"{m:,}"

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("Usage: python3 tflite_macs2.py model1.tflite [model2.tflite ...]")
        sys.exit(1)

    print(f"{'Model':<45} {'Size':>14} {'Params':>14} {'MACs':>24}")
    print("-" * 100)

    for filepath in sys.argv[1:]:
        try:
            msize, params, macs, ops, primary = parse_model(filepath)
            name = os.path.basename(filepath)
            print(f"{name:<45} {format_bytes(msize):>14} {format_bytes(params):>14} {format_macs(macs):>24}")
            print(f"  Primary ops: {primary}")
            if ops:
                print(f"  Layers with MACs ({len(ops)}):")
                for opname, m, nelems in ops[:15]:
                    print(f"    {opname:<30} MACs={format_macs(m):>20}  w_elems={nelems}")
                if len(ops) > 15:
                    print(f"    ... and {len(ops)-15} more")
        except Exception as e:
            print(f"{filepath}: ERROR - {e}")
            import traceback
            traceback.print_exc()

