bool IsPnetV3Conv1F32(const TfLiteConvParams& params,
                      const TfLiteTensor* input,
                      const TfLiteTensor* filter,
                      const TfLiteTensor* bias,
                      const TfLiteTensor* output) {
  if (input == nullptr || filter == nullptr || bias == nullptr ||
      output == nullptr) {
    return false;
  }

  const int input_dims[] = {1, 1, 276, 1};
  const int filter_dims[] = {32, 1, 21, 1};
  const int output_dims[] = {1, 1, 128, 32};
  if (input->type != kTfLiteFloat32 || filter->type != kTfLiteFloat32 ||
      bias->type != kTfLiteFloat32 || output->type != kTfLiteFloat32 ||
      !DimsEqual(input->dims, 4, input_dims) ||
      !DimsEqual(filter->dims, 4, filter_dims) ||
      !DimsEqual(output->dims, 4, output_dims) || bias->dims == nullptr ||
      (bias->dims->size != 1 && bias->dims->size != 4) ||
      NumElements(bias) != 32) {
    return false;
  }

  return params.stride_height == 1 && params.stride_width == 2 &&
         params.padding == kTfLitePaddingValid &&
         params.dilation_height_factor == 1 &&
         params.dilation_width_factor == 1 &&
         params.activation == kTfLiteActRelu;
}

