void ResetF32Profile() {
#if defined(TFLITE_MICRO_CMSIS_NN_F32_PROFILE)
  g_profile = {};
#endif
}

void RecordF32Dispatch(F32DispatchResult result, uint32_t cmsis_ticks) {
#if defined(TFLITE_MICRO_CMSIS_NN_F32_PROFILE)
  ++g_profile.attempts;
  g_profile.cmsis_ticks += cmsis_ticks;
  switch (result) {
    case F32DispatchResult::kHandled:
      ++g_profile.handled;
      break;
    case F32DispatchResult::kFallback:
      ++g_profile.fallbacks;
      break;
    case F32DispatchResult::kCmsisError:
      ++g_profile.fallbacks;
      ++g_profile.cmsis_errors;
      break;
  }
#else
  (void)result;
  (void)cmsis_ticks;
#endif
}

F32Profile GetF32Profile() {
#if defined(TFLITE_MICRO_CMSIS_NN_F32_PROFILE)
  return g_profile;
#else
  return {};
#endif
}

