                              const TfLiteEvalTensor* filter,
                              const TfLiteEvalTensor* bias,
                              TfLiteEvalTensor* output,
                              const ConvF32State& state) {
  if (!state.kernel.enabled) {
    RecordF32Dispatch(F32DispatchResult::kFallback, 0);
    return F32DispatchResult::kFallback;
  }

  void* scratch = nullptr;
  if (!GetF32ScratchBuffer(context, state.kernel, &scratch)) {
    RecordF32Dispatch(F32DispatchResult::kFallback, 0);
    return F32DispatchResult::kFallback;
  }

  cmsis_nn_context cmsis_context = {};
  cmsis_context.buf = scratch;
  cmsis_context.size = state.kernel.scratch_buffer_size;

#if defined(TFLITE_MICRO_CMSIS_NN_F32_PROFILE)
  const uint32_t start_ticks = GetCurrentTimeTicks();
#endif
  const arm_cmsis_nn_status status = arm_convolve_wrapper_f32(
      &cmsis_context, &state.params, &state.input_dims,
      tflite::micro::GetTensorData<float>(input), &state.filter_dims,
