};

// Prepares any regular NHWC Float32 Conv2D supported by CMSIS-NN. Unsupported
// shapes remain disabled so Eval can use the existing reference implementation.
TfLiteStatus PrepareConvF32(
    TfLiteContext* context, const TfLiteConvParams& params,
    const TfLiteTensor* input, const TfLiteTensor* filter,
    const TfLiteTensor* bias, const TfLiteTensor* output,
    const OpDataConv& reference_op_data, ConvF32State* state);

F32DispatchResult EvalConvF32(TfLiteContext* context,
                              const TfLiteEvalTensor* input,
                              const TfLiteEvalTensor* filter,
                              const TfLiteEvalTensor* bias,
                              TfLiteEvalTensor* output,
                              const ConvF32State& state);

}  // namespace cmsis_nn
}  // namespace tflite

#endif  // TENSORFLOW_LITE_MICRO_KERNELS_CMSIS_NN_CONV_F32_H_
