#ifndef TENSORFLOW_LITE_MICRO_KERNELS_CMSIS_NN_F32_SUPPORT_H_
#define TENSORFLOW_LITE_MICRO_KERNELS_CMSIS_NN_F32_SUPPORT_H_

#include <cstdint>

#include "tensorflow/lite/c/common.h"

namespace tflite {
namespace cmsis_nn {

enum class F32DispatchResult : uint8_t {
  kHandled = 0,
  kFallback = 1,
  kCmsisError = 2,
};

struct F32KernelState {
  bool enabled;
  int scratch_buffer_index;
  int32_t scratch_buffer_size;
};

struct F32Profile {
  uint32_t attempts;
  uint32_t handled;
  uint32_t fallbacks;
  uint32_t cmsis_errors;
  uint64_t cmsis_ticks;
};

void InitializeF32KernelState(F32KernelState* state);

// Requests optional arena scratch without making an optimization failure fatal.
// False means that the caller must retain its reference fallback path.
bool PrepareF32ScratchBuffer(TfLiteContext* context, int32_t scratch_size,
                             F32KernelState* state);

// Returns true when the prepared scratch state is usable. A null buffer is
// valid when scratch_buffer_size is zero.
bool GetF32ScratchBuffer(TfLiteContext* context, const F32KernelState& state,
                         void** buffer);

void ResetF32Profile();
void RecordF32Dispatch(F32DispatchResult result, uint32_t cmsis_ticks);
F32Profile GetF32Profile();

}  // namespace cmsis_nn
}  // namespace tflite

#endif  // TENSORFLOW_LITE_MICRO_KERNELS_CMSIS_NN_F32_SUPPORT_H_

